// Validate BEFORE the shell sees the value (Execute Command runs in a shell).
const raw = String($input.first().json.domain || '').trim().toLowerCase();
const domain = raw.replace(/^https?:\/\//, '').replace(/^.*@/, '').split('/')[0];
if (!/^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/.test(domain)) {
  throw new Error('Invalid domain: ' + raw.slice(0, 80));
}
return [{ json: { domain } }];

const report = JSON.parse($input.first().json.stdout);
const top = report.findings.filter(f => f.points > 0).sort((a, b) => b.points - a.points)[0];
return [{ json: {
  domain: report.domain,
  score: report.score,
  letter: report.letter,
  top_issue: top ? top.title : null,
  records_to_publish: report.records_to_publish,
  findings_count: report.findings.filter(f => f.points > 0).length,
  needs_help: report.score < 80
} }];
